export const ICON_CATEGORIES: string[] = ["Interface","Arrows","Commerce","Communication","People","Media","Files","Business","Technology","Social"]

const BY_ID = new Map(ICONS.map((i) => [i.id, i]))

/** Markup for an icon id, or undefined when it isn't in the set. */
export function iconSvg(id: string): string | undefined {
  return BY_ID.get(id)?.svg
}

/** Case-insensitive match over label, id and keywords. */
export function iconMatches(icon: IconDef, query: string): boolean {
  const q = query.trim().toLowerCase()
  if (!q) return true
  return `${icon.label} ${icon.id} ${icon.keywords}`.toLowerCase().includes(q)
}
